package net.officefloor.hq.app.dashboard;

import java.math.BigDecimal;
import net.officefloor.web.ObjectResponse;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * GET /api/dashboard — the home screen summary: how many clients and projects exist, how much
 * money is still owed, and how many SENT invoices are overdue. Money owed counts only invoices that
 * have actually been SENT (not drafts, and not those already paid) — the sum of every SENT
 * invoice's amount across all projects. An invoice is overdue when it is SENT and its due date is
 * before the dashboard's reference date (the seeded {@code dashboard_clock} as-of date, falling
 * back to the real current date when none is seeded).
 */
public class GetDashboard {

    public void service(JdbcTemplate jdbc, ObjectResponse<DashboardView> response) {
        long clients = jdbc.queryForObject("SELECT COUNT(*) FROM clients", Long.class);
        long projects = jdbc.queryForObject("SELECT COUNT(*) FROM projects", Long.class);
        // Money owed is the total of every SENT invoice, and an invoice's total is the sum of its
        // line items (the source of truth everywhere else) — so a cancelled (VOID) invoice, no
        // longer SENT, drops out of what is owed.
        BigDecimal outstanding = jdbc.queryForObject(
                "SELECT COALESCE(SUM(li.qty * li.unit_price), 0) FROM line_items li "
                        + "JOIN invoices inv ON inv.id = li.invoice_id WHERE inv.status = 'SENT'",
                BigDecimal.class);
        long overdue = jdbc.queryForObject(
                "SELECT COUNT(*) FROM invoices WHERE status = 'SENT' AND due_date < "
                        + "COALESCE((SELECT as_of FROM dashboard_clock WHERE id = 1), CURRENT_DATE)",
                Long.class);
        response.send(new DashboardView(clients, projects, outstanding, overdue));
    }
}

package net.officefloor.hq.app.client;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * GET /api/clients/{id}/statement — one client's statement: every invoice raised for them (across
 * all of their projects) gathered in one place, each with what is still owed on it, plus the total
 * still owed across them all.
 *
 * <p>An invoice's amount is the sum of its line items (qty * unit price); the amount still due is
 * that amount less everything paid against it (the sum of its payments). The outstanding total is
 * the sum of those dues, so a fully paid client shows nothing owed.
 */
public class GetClientStatement {

    public void service(@HttpPathParameter("id") String id, JdbcTemplate jdbc,
            ObjectResponse<ClientStatementView> response) {
        List<StatementInvoiceView> invoices = jdbc.query(
                "SELECT i.id AS id, i.project_id AS project_id, "
                        + "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li "
                        + "WHERE li.invoice_id = i.id), 0) "
                        + "- COALESCE((SELECT SUM(p.amount) FROM payments p "
                        + "WHERE p.invoice_id = i.id), 0) AS amount_due "
                        + "FROM invoices i JOIN projects pr ON pr.id = i.project_id "
                        + "WHERE pr.client_id = ? ORDER BY i.id",
                (rs, i) -> new StatementInvoiceView(rs.getLong("id"), rs.getLong("project_id"),
                        rs.getBigDecimal("amount_due")),
                Long.valueOf(id));

        BigDecimal outstanding = BigDecimal.ZERO;
        for (StatementInvoiceView invoice : invoices) {
            outstanding = outstanding.add(invoice.getAmountDue());
        }
        response.send(new ClientStatementView(invoices, outstanding));
    }
}

